  const bg=(Math.sin(gx*0.04+gy*0.025+t*0.8)+Math.sin(gx*0.03-gy*0.04+t*1.1))/2+Math.sin((gx+gy)*0.12+t*2.5)*0.2+Math.sin((gx-gy)*0.1-t*2)*0.2+Math.sin(gx*0.07+gy*0.06+t*1.5)*0.15;
